/* ============================================================================
 * level_goal_trigger_catalog.c — RCG-003 campaign goal/exit sector baseline
 * ----------------------------------------------------------------------------
 * This is the C/RE anchor for the save-state-backed matrix generated by
 * tools/level_goal_trigger_catalog.py and documented in:
 *   ObsidianVault/Systems/Level Goal and Exit Trigger Matrix.md
 *
 * SCOPE
 *   LEVEL01 already solved the native level-exit mechanism end to end:
 *     FUNC_80048138 -> FUNC_80038f38(0, &Flik+0x82)
 *       -> read runtime collision-sector region code
 *          at 0x800A7E48 + current_sector*0x30 + 0x2E.
 *
 *   RCG-003's first campaign-wide step is therefore not a new mechanism but a
 *   catalog: which loaded retail stages expose nonzero sector region codes in
 *   their runtime collision tables?
 *
 * METHOD (2026-07-02)
 *   The operator supplied level save states.  Rather than requiring a live GUI
 *   DuckStation run, the catalog tool parses DuckStation v84 save-state headers,
 *   zstd-decompresses the StateWrapper payload, locates the Bus main-RAM block,
 *   and scans the runtime sector table at 0x800A7E48.
 *
 *   Rows are kept only when:
 *     - region_code is 1..4 (the values dispatched by FUNC_80048138);
 *     - the sector's plane pointer (+0x10) lands in the collision plane arena;
 *     - origin X/Y/Z look like real world coordinates.
 *   This filters out unrelated post-table RAM after the valid sector array.
 *
 * RESULTS (runtime sector indices, SCUS-94288 save states)
 *   scene 1  / LEVEL01 / LEVEL1A: sector 177 code 2  (live-proven exit)
 *   scene 3  / LEVEL02 / LEVEL1C: sectors 570..578 code 1, sector 579 code 3
 *   scene 6  / LEVEL01 / LEVEL2C: sector 131 code 3
 *   scene 10 / LEVEL07 / LEVEL4A: sectors 292..296 code 1, sector 297 code 3
 *   scene 4  / LEVEL06 / LEVEL2A: sector 219 code 1, sectors 220..225 code 4
 *   scene 8  / LEVEL05 / LEVEL3B: sector 334 code 2
 *
 *   Other inspected stage-start saves exposed no plausible nonzero sector
 *   region codes at the loaded anchor.  That is a negative-at-anchor result,
 *   not proof that the level has no objective, because boss/special exits may
 *   be overlay-scripted or may sit elsewhere in the level.
 *
 * OPERATOR OBJECTIVE SPLIT (2026-07-02)
 *   Current RCG-003 pass should only pursue the simple "be here" endings:
 *     LEVEL02, LEVEL04, LEVEL05, LEVEL14.
 *   Conditional endings are deliberately out of scope here:
 *     LEVEL07: contact Heimlich, Slim, or Francis.
 *     LEVEL08: contact Dim, Rosie, Manny, and Tuck&Roll in any order.
 *     LEVEL10: collect bird parts _1.._5 in any order.
 *     LEVEL11: interact with all 5 ant scouts in any order, then jump into Dot.
 *     LEVEL13: walk into Atta after the Hopper/Atta setup; setup is out of scope.
 *   Boss endings are a separate gap from this sector-table catalog.
 *
 * LIVE BE-HERE ROUTE PROOF (2026-07-02)
 *   Tool: tools/prove_be_here_endings.py
 *   Capture: build/rcg003_be_here_probe.json
 *   Disc: ~/Downloads/ABL/Disney-Pixar A Bug's Life (v1.0).cue
 *
 *   With load-state validation enabled and only DuckStation controller input:
 *     LEVEL02_ENDING.sav: hold UP -> sector 579 -> [0x800823A0]=1.
 *     LEVEL04_ENDING.sav: hold UP -> sector 131 -> [0x800823A0]=1.
 *     LEVEL05_ENDING.sav: hold UP -> sector 297 -> [0x800823A0]=1.
 *     LEVEL14_ENDING_1.sav: press START, then hold UP -> [0x800823A0]=1.
 *
 *   Access-log data PCs are post-access in this DuckStation fork:
 *     reported 0x800496fc => true store at 0x800496f8 for LEVEL02/04/05.
 *     reported 0x800496dc => true store at 0x800496d8 for LEVEL14.
 *   The LEVEL14 final sampled sector was 242, so record it as latch-path
 *   completion proof rather than proof that the static sector-334 row was the
 *   crossed surface in that particular replay.
 *
 * REGION-CODE SEMANTICS
 *   code 1: FUNC_80048138 calls FUNC_8004A700 (type-2 transition path).
 *           Destination/resource setup remains per-level semantic work.
 *   code 2: type-1 exit body; sets [0x800823A0]=1, fade [0x80082470]=23,
 *           calls FUNC_80050994(58,0).  Live-proven on LEVEL01.
 *   code 3/4: nonzero dispatch cases in the same resident player/exit handler.
 *             The catalog proves their runtime sector placement, not their full
 *             gameplay meaning yet.
 *
 * RESIDUAL RCG-003
 *   - Decode the code-3/code-4 dispatch bodies and FUNC_8004A700 destination
 *     semantics.
 *   - Conditional and boss/special level completion still belongs to separate
 *     overlay/objective tracing, not this sector-table-only catalog.
 *   - Exact source-side edit offsets for non-LEVEL01 trigger sectors require
 *     per-level FUNC_80030F60/source-record tracing.  Runtime indices are known;
 *     disc-source record offsets are not all proven.
 * ========================================================================== */

#include "re_types.h"

#define G_FLIK_BASE             0x800a6500
#define G_FLIK_GATE             (*(volatile u8  *)0x800a6582)
#define G_CURRENT_SECTOR        (*(volatile s32 *)0x80090560)
#define G_TRANSITION_LEVER      (*(volatile s16 *)0x800823a0)
#define G_FADE_COLOR            (*(volatile s16 *)0x80082470)

#define SECTOR_TABLE_BASE       0x800a7e48
#define SECTOR_STRIDE           0x30
#define SECTOR_ORIGIN_X         0x00
#define SECTOR_ORIGIN_Y         0x04
#define SECTOR_ORIGIN_Z         0x08
#define SECTOR_PLANE_PTR        0x10
#define SECTOR_REGION_CODE      0x2e

#define REGION_NONE             0
#define REGION_TYPE2_PATH       1
#define REGION_TYPE1_EXIT       2
#define REGION_CASE3_UNKNOWN    3
#define REGION_CASE4_UNKNOWN    4

extern void FUNC_8004A700(s32 a0, s32 a1, void *a2, s32 a3);
extern s32  FUNC_80050994(s32 sfx, s32 a1);

struct CollisionSectorRuntime {
    s32 origin_x;
    s32 origin_y;
    s32 origin_z;
    s32 unknown_0c;
    void *plane_block;
    s32 aabb_min_x;
    s32 unknown_18;
    s32 aabb_min_z;
    s32 extent_x;
    s32 extent_z;
    s32 unknown_28;
    s16 flags;
    s16 region_code;
};

static volatile struct CollisionSectorRuntime *sector_table(void)
{
    return (volatile struct CollisionSectorRuntime *)SECTOR_TABLE_BASE;
}

s16 rcg003_current_sector_region_code(void)
{
    if (G_FLIK_GATE != 1)
        return REGION_NONE;

    return sector_table()[G_CURRENT_SECTOR].region_code;
}

void rcg003_documented_dispatch_slice(void)
{
    s16 code = rcg003_current_sector_region_code();
    if (code == REGION_NONE || G_TRANSITION_LEVER != 0)
        return;

    switch (code) {
    case REGION_TYPE2_PATH:
        FUNC_8004A700(0, 0, (void *)0, 1);
        break;
    case REGION_TYPE1_EXIT:
        G_TRANSITION_LEVER = 1;
        G_FADE_COLOR = 23;
        FUNC_80050994(58, 0);
        break;
    case REGION_CASE3_UNKNOWN:
    case REGION_CASE4_UNKNOWN:
        /* Resident cases exist; full semantics are RCG-003 follow-up. */
        break;
    }
}
